create or replace function private.manage_group_member(p_conversation_id uuid,p_target_user_id uuid,p_action text) returns boolean language plpgsql security definer set search_path = '' as $$ declare v_actor uuid := (select auth.uid()); v_owner uuid; v_actor_is_admin boolean; v_target_role text; begin if v_actor is null then raise exception 'يجب تسجيل الدخول أولاً'; end if; if p_action is null or p_action not in ('promote','demote','remove') then raise exception 'إجراء غير صالح'; end if; select c.user_one into v_owner from public.conversations c where c.id=p_conversation_id and c.is_group=true; if v_owner is null then raise exception 'المجموعة غير موجودة'; end if; if v_actor=p_target_user_id then raise exception 'لا يمكنك تنفيذ هذا الإجراء على نفسك'; end if; v_actor_is_admin := v_actor=v_owner or exists(select 1 from public.conversation_members cm where cm.conversation_id=p_conversation_id and cm.user_id=v_actor and cm.role='admin'); if not v_actor_is_admin then raise exception 'هذه العملية متاحة لمشرفي المجموعة فقط'; end if; select cm.role into v_target_role from public.conversation_members cm where cm.conversation_id=p_conversation_id and cm.user_id=p_target_user_id for update; if not found then raise exception 'هذا الشخص ليس عضواً في المجموعة'; end if; if p_action in ('promote','demote') then if v_actor<>v_owner then raise exception 'تغيير صلاحيات المشرفين متاح لمنشئ المجموعة فقط'; end if; if p_action='promote' and v_target_role<>'admin' then update public.conversation_members set role='admin' where conversation_id=p_conversation_id and user_id=p_target_user_id; elsif p_action='demote' and v_target_role='admin' then update public.conversation_members set role='member' where conversation_id=p_conversation_id and user_id=p_target_user_id; end if; return true; end if; if v_target_role='admin' and v_actor<>v_owner then raise exception 'لا يمكن للمشرف إزالة مشرف آخر'; end if; delete from public.conversation_members where conversation_id=p_conversation_id and user_id=p_target_user_id; return true; end; $$; revoke all on function private.manage_group_member(uuid,uuid,text) from public,anon; grant execute on function private.manage_group_member(uuid,uuid,text) to authenticated;
